// Ngân hàng câu hỏi Tiếng Việt / Ngữ văn, Tiếng Anh, Khoa học — lớp 1 đến lớp 9.
// Cú pháp rút gọn:  'tiếng việt|english'  (không có dấu | thì hai ngôn ngữ giống nhau).
//   M(câu hỏi, đáp án đúng, ...nhiễu)          → trắc nghiệm
//   B(câu có ___, đáp án đúng, ...nhiễu)       → điền chỗ trống
//   H(từ đọc, ngôn ngữ đọc, đúng, ...nhiễu)    → nghe và chọn
//   T(nhận định, đúng/sai)                     → đúng / sai
//   P(yêu cầu, [[trái, phải], ...])            → nối cặp / lật thẻ
//   O(yêu cầu, [thứ tự đúng...])               → sắp xếp
//   W(từ đáp án, gợi ý)                        → ghép chữ
//   C(yêu cầu, [đúng...], [sai...])            → hứng đồ

const S = (s) => { const [vi, en] = String(s).split('|'); return { vi, en: en ?? vi }; };
const M = (q, ...opts) => ({ kind: 'mc', prompt: S(q), options: opts.map(S) });
const B = (q, ...opts) => ({ kind: 'mc', blank: true, prompt: S(q), options: opts.map(S) });
const H = (say, lang, ...opts) => ({ kind: 'mc', listen: true, say: { text: say, lang }, prompt: S('Nghe và chọn đáp án đúng|Listen and choose'), options: opts.map(S) });
const T = (q, a) => ({ kind: 'tf', prompt: S(q), answer: a });
const P = (q, pairs) => ({ kind: 'pairs', prompt: S(q), pairs: pairs.map(([a, b]) => [S(a), S(b)]) });
const O = (q, items) => ({ kind: 'order', prompt: S(q), items: items.map(S) });
const W = (answer, q) => ({ kind: 'word', prompt: S(q), answer });
const C = (q, ok, bad) => ({ kind: 'classify', prompt: S(q), items: [...ok.map((t) => ({ t: S(t), ok: true })), ...bad.map((t) => ({ t: S(t), ok: false }))] });

